import java.io.BufferedReader;import java.io.IOException;import java.io.InputStreamReader;import java.util.Arrays;import java.util.StringTokenizer;public class Main {static class FastScanner {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));StringTokenizer st;String next() {while (st == null || !st.hasMoreTokens()) {try {String l = br.readLine();if (l == null) return null;st = new StringTokenizer(l);} catch (IOException e) {return null;}}return st.nextToken();}boolean hasNext() {while (st == null || !st.hasMoreTokens()) {try {String l = br.readLine();if (l == null) return false;st = new StringTokenizer(l);} catch (IOException e) {return false;}}return true;}int nextInt() {return Integer.parseInt(next());}long nextLong() {return Long.parseLong(next());}double nextDouble() {return Double.parseDouble(next());}String nextLine() {st = null;try {return br.readLine();} catch (IOException e) {return null;}}}public static void main(String[] args) {FastScanner scanner = new FastScanner();if (!scanner.hasNext()) return;int n = scanner.nextInt();int a = scanner.nextInt();int b = scanner.nextInt();int c = scanner.nextInt();int[] dp = new int[n + 1];Arrays.fill(dp, -1);dp[0] = 0;for (int i = 1; i <= n; i++) {if (i >= a && dp[i - a] != -1) {dp[i] = Math.max(dp[i], dp[i - a] + 1);}if (i >= b && dp[i - b] != -1) {dp[i] = Math.max(dp[i], dp[i - b] + 1);}if (i >= c && dp[i - c] != -1) {dp[i] = Math.max(dp[i], dp[i - c] + 1);}}System.out.println(dp[n]);}}